import SwiftUI

struct LoginScreen: View {
    enum OTPChannel: String {
        case email
        case sms
    }

    enum LoginFailureReason: String {
        case invalidOtp
        case expired
        case locked
        case network
    }

    struct OTPSentPayload {
        let channel: OTPChannel
    }

    struct LoginSucceededPayload {
        let userId: String
    }

    struct LoginFailedPayload {
        let reason: LoginFailureReason
    }

    var identifier: String = ""
    var prefillIdentifier: String? = nil

    var onOtpSent: ((OTPSentPayload) -> Void)? = nil
    var onOtpResent: (() -> Void)? = nil
    var onLoginSucceeded: ((LoginSucceededPayload) -> Void)? = nil
    var onLoginFailed: ((LoginFailedPayload) -> Void)? = nil

    @State private var enteredIdentifier: String = ""
    @State private var otpCode: String = ""
    @State private var otpRequested: Bool = false
    @State private var failedAttempts: Int = 0
    @State private var isLocked: Bool = false

    var body: some View {
        VStack(alignment: .leading, spacing: 16) {
            Text("Login-Screen mit OTP")
                .font(.title)
                .accessibilityAddTraits(.isHeader)

            Text("Identifier: \(identifier)")
            if let prefill = prefillIdentifier {
                Text("Prefill: \(prefill)")
            }

            TextField("E-Mail oder Telefon", text: $enteredIdentifier)
                .textFieldStyle(.roundedBorder)
                .disabled(isLocked)
                .accessibilityLabel("Identifier-Eingabe")

            Button("Submit") {
                otpRequested = true
                let channel: OTPChannel = enteredIdentifier.contains("@") ? .email : .sms
                onOtpSent?(OTPSentPayload(channel: channel))
            }
            .disabled(isLocked || enteredIdentifier.isEmpty)

            if otpRequested {
                Text("OTP-Code (6-stellig)")
                TextField("000000", text: $otpCode)
                    .textFieldStyle(.roundedBorder)
                    .disabled(isLocked)
                    .accessibilityLabel("OTP-Eingabe")

                HStack {
                    Button("Bestätigen") {
                        if isLocked {
                            onLoginFailed?(LoginFailedPayload(reason: .locked))
                            return
                        }
                        if otpCode == "000000" {
                            failedAttempts += 1
                            if failedAttempts >= 5 {
                                isLocked = true
                                onLoginFailed?(LoginFailedPayload(reason: .locked))
                            } else {
                                onLoginFailed?(LoginFailedPayload(reason: .invalidOtp))
                            }
                        } else {
                            onLoginSucceeded?(LoginSucceededPayload(userId: enteredIdentifier))
                        }
                    }
                    .disabled(isLocked)

                    Button("Resend") {
                        onOtpResent?()
                    }
                    .disabled(isLocked)
                }
            }

            if isLocked {
                Text("Konto gesperrt. Bitte 15 Minuten warten.")
                    .foregroundColor(.red)
                    .accessibilityLabel("Lockout-Hinweis")
            }

            Text("Fehlversuche: \(failedAttempts)/5")
                .font(.footnote)
        }
        .padding()
        .onAppear {
            if let prefill = prefillIdentifier, enteredIdentifier.isEmpty {
                enteredIdentifier = prefill
            } else if enteredIdentifier.isEmpty {
                enteredIdentifier = identifier
            }
        }
    }
}
